import * as React from "react";
import { Card, Box, BlockStack, InlineStack, Text, Button } from "@xco-agency/corex-ui";
import type { AppCrossSellPropsType } from "./types";
import { DEFAULT_APPS_LIST, DEFAULT_DISCOUNT_TIERS } from "./constants";
import { AppCrossSellTierProgress } from "./partials/AppCrossSellTierProgress";
import { AppCrossSellRow } from "./partials/AppCrossSellRow";
import { getMaxDiscount, getNextTier } from "./utils";

const COLLAPSED_APP_COUNT = 5;

export function AppCrossSell({
  title,
  description = "The more apps you install, the higher your revenue, the bigger your discount on all of them.",
  tiers = DEFAULT_DISCOUNT_TIERS,
  apps = DEFAULT_APPS_LIST,
  onInstall,
  onDismiss,
  installedCount,
}: AppCrossSellPropsType) {
  const [showAll, setShowAll] = React.useState(false);
  const [installingId, setInstallingId] = React.useState<string | null>(null);

  const currentInstalledCount =
    installedCount !== undefined
      ? installedCount
      : apps.filter((app) => app.installed).length;

  const resolvedTitle =
    title ?? `Get more from every customer and save up to ${getMaxDiscount(tiers)}%`;
  const nextTier = getNextTier(tiers, currentInstalledCount);
  const installLabel = nextTier
    ? `Install to unlock ${nextTier.discountPercent}% off`
    : "Install";

  // Apps still to install come first, so the collapsed list shows what matters.
  const sortedApps = [...apps].sort((a, b) => Number(a.installed) - Number(b.installed));
  const displayedApps = showAll ? sortedApps : sortedApps.slice(0, COLLAPSED_APP_COUNT);

  const handleInstall = async (appId: string) => {
    setInstallingId(appId);
    try {
      await onInstall?.(appId);
    } finally {
      setInstallingId(null);
    }
  };

  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="flex-start" gap="base">
          <BlockStack gap="small-300">
            <Text variant="headingMd" as="h2" fontWeight="bold">
              {resolvedTitle}
            </Text>
            <Text variant="bodySm" color="subdued" as="p">
              {description}
            </Text>
          </BlockStack>

          {onDismiss && (
            <Button
              variant="tertiary"
              icon="x"
              accessibilityLabel="Dismiss promotion"
              onClick={onDismiss}
            />
          )}
        </InlineStack>

        <AppCrossSellTierProgress tiers={tiers} installedCount={currentInstalledCount} />

        <Box
          borderWidth="small-100"
          borderColor="border"
          borderRadius="base"
          background="bg-surface"
          overflow="hidden"
        >
          {displayedApps.map((app, index) => (
            <AppCrossSellRow
              key={app.id}
              app={app}
              installLabel={installLabel}
              installing={installingId === app.id}
              onInstall={handleInstall}
              isLast={
                index === displayedApps.length - 1 && !(apps.length > COLLAPSED_APP_COUNT)
              }
            />
          ))}

          {apps.length > COLLAPSED_APP_COUNT && (
            <Box
              padding="small-200 base"
              borderBlockStartWidth="small-100"
              borderColor="border-subdued"
              background="bg-surface-secondary"
            >
              <InlineStack justifyContent="center">
                <Button variant="tertiary" onClick={() => setShowAll(!showAll)}>
                  {showAll ? "Show fewer apps" : `View all ${apps.length} available apps`}
                </Button>
              </InlineStack>
            </Box>
          )}
        </Box>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import { Box, BlockStack, InlineStack, Button, Page, Text } from "@xco-agency/corex-ui";
import { AppCrossSell } from "../AppCrossSell";
import { DEFAULT_APPS_LIST, DEFAULT_DISCOUNT_TIERS } from "../constants";
import type { AppCrossSellItemType } from "../types";

export function AppCrossSellExample() {
  const [apps, setApps] = React.useState<AppCrossSellItemType[]>(DEFAULT_APPS_LIST);
  const [isDismissed, setIsDismissed] = React.useState(false);

  const installedCount = apps.filter((app) => app.installed).length;

  // Stand-in for the real install round trip, so the row shows its loading state.
  const handleInstall = (appId: string) =>
    new Promise<void>((resolve) => {
      setTimeout(() => {
        setApps((current) =>
          current.map((app) => (app.id === appId ? { ...app, installed: true } : app)),
        );
        resolve();
      }, 700);
    });

  const handleReset = () => {
    setApps(DEFAULT_APPS_LIST);
    setIsDismissed(false);
  };

  return (
    <Page
      heading="Partner apps"
      subtitle="Install more apps from the same team and save on all of them."
      inlineSize="large"
      secondaryActions={[{ content: "Reset demo", onAction: handleReset }]}
    >
      <BlockStack gap="base">
        {!isDismissed ? (
          <AppCrossSell
            apps={apps}
            tiers={DEFAULT_DISCOUNT_TIERS}
            installedCount={installedCount}
            onInstall={handleInstall}
            onDismiss={() => setIsDismissed(true)}
          />
        ) : (
          <Box padding="base" background="subdued" borderRadius="base">
            <InlineStack justifyContent="space-between" alignItems="center">
              <Text color="subdued">Cross-sell promotion banner was dismissed.</Text>
              <Button variant="secondary" onClick={() => setIsDismissed(false)}>
                Restore banner
              </Button>
            </InlineStack>
          </Box>
        )}
      </BlockStack>
    </Page>
  );
}

import * as React from "react";
import {
  Card,
  Box,
  BlockStack,
  InlineStack,
  Grid,
  Page,
  Text,
  Badge,
  Button,
} from "@xco-agency/corex-ui";
import { AppIconBadge } from "../partials/AppIconBadge";
import { AppCrossSellTierProgress } from "../partials/AppCrossSellTierProgress";
import { DEFAULT_APPS_LIST, DEFAULT_DISCOUNT_TIERS } from "../constants";
import type { AppCrossSellItemType } from "../types";
import { getMaxDiscount, getNextTier } from "../utils";

export function AppCrossSellGridExample() {
  const [apps, setApps] = React.useState<AppCrossSellItemType[]>(DEFAULT_APPS_LIST);

  const installedCount = apps.filter((a) => a.installed).length;
  const displayedApps = apps.slice(0, 6);
  const nextTier = getNextTier(DEFAULT_DISCOUNT_TIERS, installedCount);
  const installLabel = nextTier
    ? `Install to unlock ${nextTier.discountPercent}% off`
    : "Install app";

  const handleInstall = (id: string) => {
    setApps((current) =>
      current.map((a) => (a.id === id ? { ...a, installed: true } : a)),
    );
  };

  return (
    <Page heading="Partner apps" inlineSize="large">
      <Card>
        <BlockStack gap="base">
          {/* Header */}
          <BlockStack gap="small-300">
            <Text variant="headingMd" as="h2" fontWeight="bold">
              {`Get more from every customer and save up to ${getMaxDiscount(DEFAULT_DISCOUNT_TIERS)}%`}
            </Text>
            <Text variant="bodySm" color="subdued" as="p">
              The more apps you install, the higher your revenue, the bigger your discount
              on all of them.
            </Text>
          </BlockStack>

          {/* Stepper progress */}
          <AppCrossSellTierProgress
            tiers={DEFAULT_DISCOUNT_TIERS}
            installedCount={installedCount}
          />

          {/* 3-Column App Cards Grid */}
          <Grid columns={{ sm: 1, md: 2, lg: 3 }} gap="base">
            {displayedApps.map((app) => (
              <Box
                key={app.id}
                borderWidth="small-100"
                borderColor="border"
                borderRadius="base"
                padding="base"
                background="bg-surface"
              >
                <BlockStack gap="base">
                  <BlockStack gap="small-300">
                    <InlineStack justifyContent="space-between" alignItems="flex-start">
                      <AppIconBadge
                        type={app.iconType}
                        bg={app.iconBg}
                        name={app.name}
                        size={44}
                      />

                      {app.installed ? (
                        <Badge tone="success">Installed</Badge>
                      ) : app.builtForShopify ? (
                        <Badge tone="info">Built for Shopify</Badge>
                      ) : null}
                    </InlineStack>

                    <BlockStack gap="small-500">
                      <Text variant="bodyMd" fontWeight="bold">
                        {app.name}
                      </Text>

                      {app.rating && (
                        <InlineStack gap="small-400" alignItems="center">
                          <Text variant="bodySm" fontWeight="semibold">
                            ★ {app.rating.toFixed(1)}
                          </Text>
                          {app.reviewsCount && (
                            <Text variant="bodySm" color="subdued">
                              ({app.reviewsCount})
                            </Text>
                          )}
                          {app.pricingBadge && (
                            <Text variant="bodySm" color="subdued">
                              • {app.pricingBadge}
                            </Text>
                          )}
                        </InlineStack>
                      )}
                    </BlockStack>

                    <Text variant="bodySm" color="subdued" as="p">
                      {app.category}
                    </Text>
                  </BlockStack>

                  <Box
                    borderBlockStartWidth="small-100"
                    borderColor="border-subdued"
                    paddingBlockStart="small-200"
                  >
                    {app.installed ? (
                      <Button fullWidth disabled>
                        Installed on store
                      </Button>
                    ) : (
                      <Button
                        fullWidth
                        variant="primary"
                        onClick={() => handleInstall(app.id)}
                      >
                        {installLabel}
                      </Button>
                    )}
                  </Box>
                </BlockStack>
              </Box>
            ))}
          </Grid>
        </BlockStack>
      </Card>
    </Page>
  );
}

export { AppCrossSell } from "./AppCrossSell";
export { AppCrossSellExample } from "./examples/AppCrossSellExample";
export { AppCrossSellGridExample } from "./examples/AppCrossSellGridExample";
export * from "./types";
export * from "./constants";
export * from "./utils";

import * as React from "react";
import { Box, BlockStack, InlineStack, Text, Badge, Button } from "@xco-agency/corex-ui";
import type { AppCrossSellItemType } from "../types";
import { AppIconBadge } from "./AppIconBadge";

export type AppCrossSellRowPropsType = {
  app: AppCrossSellItemType;
  onInstall?: (id: string) => void;
  /** Button label, e.g. "Install to unlock 20% off". */
  installLabel?: string;
  /** Shows the install button as busy while the install runs. */
  installing?: boolean;
  isLast?: boolean;
};

export function AppCrossSellRow({
  app,
  onInstall,
  installLabel = "Install",
  installing = false,
  isLast = false,
}: AppCrossSellRowPropsType) {
  return (
    <Box
      padding="small-200 base"
      borderBlockEndWidth={isLast ? "none" : "small-100"}
      borderColor="border-subdued"
    >
      <InlineStack justifyContent="space-between" alignItems="center" gap="base">
        {/* App identity */}
        <InlineStack gap="base" alignItems="center">
          <AppIconBadge
            type={app.iconType}
            bg={app.iconBg}
            logoUrl={app.logoUrl}
            name={app.name}
            size={38}
          />
          <BlockStack gap="small-500">
            <InlineStack gap="small-200" alignItems="center" wrap>
              <Text variant="base" fontWeight="semibold">
                {app.name}
              </Text>
              {app.builtForShopify && <Badge tone="info">Built for Shopify</Badge>}
            </InlineStack>
            {app.category && (
              <Text variant="xs" color="subdued">
                {app.category}
              </Text>
            )}
            {app.rating || app.pricingBadge ? (
              <Text variant="xs" color="subdued">
                {[
                  app.rating
                    ? `★ ${app.rating.toFixed(1)}${app.reviewsCount ? ` (${app.reviewsCount})` : ""}`
                    : null,
                  app.pricingBadge,
                ]
                  .filter(Boolean)
                  .join(" · ")}
              </Text>
            ) : null}
          </BlockStack>
        </InlineStack>

        {/* Action / Status */}
        <InlineStack shrink={false}>
          {app.installed ? (
            <Badge tone="success" size="base">
              Installed
            </Badge>
          ) : (
            <Button
              variant="secondary"
              loading={installing}
              onClick={() => onInstall?.(app.id)}
            >
              {installLabel}
            </Button>
          )}
        </InlineStack>
      </InlineStack>
    </Box>
  );
}

import * as React from "react";
import {
  Badge,
  BlockStack,
  Box,
  Icon,
  InlineStack,
  ProgressBar,
  Text,
} from "@xco-agency/corex-ui";
import type { DiscountTierType } from "../types";
import { getNextTier, getReachedTier, pluralizeApps } from "../utils";

export type AppCrossSellTierProgressPropsType = {
  tiers: DiscountTierType[];
  installedCount?: number;
};

/** Discount progress: current tier, what is left to unlock, and the tier milestones. */
export function AppCrossSellTierProgress({
  tiers,
  installedCount = 0,
}: AppCrossSellTierProgressPropsType) {
  const reached = getReachedTier(tiers, installedCount);
  const next = getNextTier(tiers, installedCount);
  const target = tiers[tiers.length - 1]?.appsCount ?? 1;

  return (
    <BlockStack gap="small-200">
      <InlineStack
        justifyContent="space-between"
        alignItems="center"
        gap="small-200"
        wrap
      >
        <InlineStack gap="small-200" alignItems="center">
          <Text variant="bodySm" fontWeight="semibold">
            {`${pluralizeApps(installedCount)} installed`}
          </Text>
          {reached ? (
            <Badge tone="success">{`${reached.discountPercent}% discount active`}</Badge>
          ) : (
            <Badge tone="neutral">No discount yet</Badge>
          )}
        </InlineStack>

        <Text variant="bodySm" color="subdued">
          {next
            ? `Install ${pluralizeApps(next.appsCount - installedCount)} more to unlock ${next.discountPercent}% off`
            : "Maximum discount unlocked"}
        </Text>
      </InlineStack>

      <ProgressBar
        value={Math.min(installedCount, target)}
        max={target}
        tone={next ? "info" : "success"}
        accessibilityLabel="Apps installed toward the next discount"
      />

      <InlineStack
        justifyContent="space-between"
        alignItems="center"
        gap="small-200"
        wrap
      >
        {tiers.map((tier, index) => {
          const isReached = installedCount >= tier.appsCount;

          return (
            <React.Fragment key={tier.id}>
              <Box
                background={isReached ? "subdued" : "base"}
                borderWidth="small-100"
                borderColor={isReached ? "base" : "subdued"}
                borderRadius="large-100"
                padding="small-200 base"
              >
                <InlineStack gap="small-200" alignItems="center">
                  {isReached ? <Icon type="check" size="small" tone="success" /> : null}
                  <Text
                    variant="bodySm"
                    fontWeight={isReached ? "semibold" : "medium"}
                    color={isReached ? "success" : "subdued"}
                  >
                    {tier.label}
                  </Text>
                </InlineStack>
              </Box>

              {index < tiers.length - 1 && <Icon type="arrow-right" tone="neutral" />}
            </React.Fragment>
          );
        })}
      </InlineStack>
    </BlockStack>
  );
}

export type AppCrossSellItemType = {
  id: string;
  name: string;
  category?: string;
  installed: boolean;
  iconBg?: string;
  iconType?: string;
  logoUrl?: string;
  appUrl?: string;
  rating?: number;
  reviewsCount?: number;
  pricingBadge?: string;
  builtForShopify?: boolean;
};

export type DiscountTierType = {
  id: string;
  appsCount: number;
  discountPercent: number;
  label: string;
};

export type AppCrossSellPropsType = {
  title?: string;
  description?: string;
  tiers?: DiscountTierType[];
  apps?: AppCrossSellItemType[];
  /** May return a promise; the row shows a loading state until it settles. */
  onInstall?: (appId: string) => void | Promise<void>;
  onDismiss?: () => void;
  installedCount?: number;
};

import type { DiscountTierType } from "./types";

/** Highest tier unlocked by `installedCount` apps, or `null` before the first. */
export const getReachedTier = (tiers: DiscountTierType[], installedCount: number) =>
  [...tiers].reverse().find((tier) => installedCount >= tier.appsCount) ?? null;

/** Next tier still to unlock, or `null` once the top tier is reached. */
export const getNextTier = (tiers: DiscountTierType[], installedCount: number) =>
  tiers.find((tier) => installedCount < tier.appsCount) ?? null;

/** Biggest discount on offer, for headlines such as "save up to 30%". */
export const getMaxDiscount = (tiers: DiscountTierType[]) =>
  Math.max(0, ...tiers.map((tier) => tier.discountPercent));

export const pluralizeApps = (count: number) => `${count} app${count === 1 ? "" : "s"}`;
